    """Exact 3-colourability via backtracking."""
    n = instance["n"]
    adj = [[] for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].append(v)
        adj[v].append(u)
    colour = [-1] * n

    def rec(i: int) -> bool:
        if i == n:
            return True
        for c in range(3):
            if all(colour[j] != c for j in adj[i]):
                colour[i] = c
                if rec(i + 1):
                    return True
                colour[i] = -1
        return False

    return rec(0)


def solve_three_coloring_enumerate(instance: dict) -> bool:
    """Independent exhaustive check over all 3^n colourings."""
    n = instance["n"]
    edges = instance["edges"]
    for assign in itertools.product(range(3), repeat=n):
        if all(assign[u] != assign[v] for u, v in edges):
            return True
    return False


def solve_three_sat(instance: dict) -> bool:
    """Exact 3-SAT via DPLL with unit propagation."""
    clauses = [tuple(c) for c in instance["clauses"]]

    def propagate(assign: dict) -> dict | None:
        changed = True
        while changed:
            changed = False
            for cl in clauses:
                unassigned = []
                satisfied = False
                for lit in cl:
                    val = assign.get(abs(lit))
                    if val is None:
                        unassigned.append(lit)
                    elif val == (lit > 0):
                        satisfied = True
                        break
                if satisfied:
                    continue
                if not unassigned:
                    return None
                if len(unassigned) == 1:
                    lit = unassigned[0]
                    v, val = abs(lit), lit > 0
                    if v in assign:
                        if assign[v] != val:
                            return None
                    else:
                        assign[v] = val
                        changed = True
        return assign

    def rec(assign: dict) -> bool:
        assign = dict(assign)
        if propagate(assign) is None:
            return False
        var = next((abs(l) for cl in clauses for l in cl if abs(l) not in assign), None)
